using System.ComponentModel.DataAnnotations;

namespace Visma.Core.Entities;

/// <summary>
/// A person who comes to the premises. A visitor is registered ONCE and can then make
/// many <see cref="Visit"/>s (returning-visitor support). Phone number is the natural
/// identifier used to look a returning visitor up, so it is unique in the database.
/// </summary>
public class Visitor
{
    /// <summary>Primary key (auto-generated by the database).</summary>
    public int Id { get; set; }

    /// <summary>Visitor's full name, e.g. "Ada Okafor".</summary>
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, MinimumLength = 2, ErrorMessage = "Full name must be between 2 and 100 characters.")]
    [Display(Name = "Full name")]
    public string FullName { get; set; } = string.Empty;

    /// <summary>Phone number. Required and unique: this is how returning visitors are found.</summary>
    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Enter a valid phone number.")]
    [StringLength(20, MinimumLength = 7, ErrorMessage = "Phone number must be between 7 and 20 characters.")]
    [Display(Name = "Phone number")]
    public string Phone { get; set; } = string.Empty;

    /// <summary>Optional e-mail address (also usable for returning-visitor lookup).</summary>
    [EmailAddress(ErrorMessage = "Enter a valid e-mail address.")]
    [StringLength(100)]
    [Display(Name = "E-mail")]
    public string? Email { get; set; }

    /// <summary>Optional organisation the visitor represents.</summary>
    [StringLength(100)]
    public string? Company { get; set; }

    /// <summary>When the visitor was first registered (UTC).</summary>
    [Display(Name = "Registered")]
    public DateTime CreatedAt { get; set; }

    /// <summary>All visits this visitor has made (navigation property, 1-to-many).</summary>
    public ICollection<Visit> Visits { get; set; } = new List<Visit>();
}
